-- public.hull_speed(p_world uuid, p_uid uuid, p placed)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.hull_speed(p_world uuid, p_uid uuid, p placed)
 RETURNS double precision
 LANGUAGE sql
 STABLE
AS $function$
  select b.speed
       * case when b.sail then 0.9 + skill_of(p_world, p_uid, 'body_control') / 320
              else 0.6 + skill_of(p_world, p_uid, 'body_strength') / 150 end
       * (0.75 + p.ql / 220)
       * case when b.sail then weather_most() else 1 end
  from boat_def b where b.id = p.sub
$function$
